def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def pos(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return default

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(src, dst):
        return [clamp_step(dst[0] - src[0]), clamp_step(dst[1] - src[1])]

    def step_away(src, dst):
        return [clamp_step(src[0] - dst[0]), clamp_step(src[1] - dst[1])]

    def nearest(points, src):
        best = None
        best_d = None
        for p in points or []:
            if isinstance(p, (list, tuple)) and len(p) >= 2:
                d = manhattan(src, (p[0], p[1]))
                if best is None or d < best_d:
                    best = (p[0], p[1])
                    best_d = d
        return best

    def farthest(points, src):
        best = None
        best_d = None
        for p in points or []:
            if isinstance(p, (list, tuple)) and len(p) >= 2:
                d = manhattan(src, (p[0], p[1]))
                if best is None or d > best_d:
                    best = (p[0], p[1])
                    best_d = d
        return best

    env = observation.get("environment_name", "resource_collection")
    sx, sy = pos(observation.get("self_position", (0, 0)))
    ox, oy = pos(observation.get("opponent_position", (sx, sy)))
    self_p = (sx, sy)
    opp_p = (ox, oy)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            target = opp_p
            return step_toward(self_p, target)
        w = observation.get("grid_width", 0) or 0
