        target = farthest(corners, opp_p) or farthest(corners, self_p) or (0, 0)
        return step_toward(self_p, target)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier_cells") or []
        target = nearest(targets, self_p)
        if target is not None:
            return step_toward(self_p, target)
        opp_terr = observation.get("opponent_territory") or []
        target = nearest(opp_terr, self_p)
        if target is not None:
            return step_toward(self_p, target)
        return step_away(self_p, opp_p)

    resources = observation.get("resources") or observation.get("resource_positions") or observation.get("resource_cells") or []
    target = nearest(resources, self_p)
    if target is not None:
        return step_toward(self_p, target)

    # Fallbacks for all modes: pressure opponent if close, otherwise explore away from them.
    if manhattan(self_p, opp_p) <= 2:
        return step_away(self_p, opp_p)

    w = observation.get("grid_width", 0) or 0
    h = observation.get("grid_height", 0) or 0
    if w and h:
        cx = w // 2
        cy = h // 2
        return step_toward(self_p, (cx, cy))

    return [0, 0]

